def rotate_rays_cw(grid):
    """Each 2-block's four diagonal corner rays are extended to the grid edge, with the rays' colors rotated 90 degrees clockwise around the block."""
    h,w=len(grid),len(grid[0])
    out=[[0]*w for _ in range(h)]
    # find 2-components
    seen=set(); blocks=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j]==2 and (i,j) not in seen:
                comp=[(i,j)]; seen.add((i,j)); k=0
                while k<len(comp):
                    r,c=comp[k]; k+=1
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=r+dr,c+dc
                        if 0<=a<h and 0<=b<w and grid[a][b]==2 and (a,b) not in seen:
                            seen.add((a,b)); comp.append((a,b))
                blocks.append(comp)
    for comp in blocks:
        rs=[r for r,c in comp]; cs=[c for r,c in comp]
        rt,rb,cl,cr=min(rs),max(rs),min(cs),max(cs)
        for r,c in comp: out[r][c]=2
        # corners: (row side, col side) -> outward step
        corners=[(rt,cl,-1,-1),(rt,cr,-1,1),(rb,cr,1,1),(rb,cl,1,-1)]  # TL,TR,BR,BL in CW order
        colors={}
        for (r,c,dr,dc) in corners:
            a,b=r+dr,c+dc
            colors[(r,c,dr,dc)] = grid[a][b] if 0<=a<h and 0<=b<w else 0
        order=[(rt,cl,-1,-1),(rt,cr,-1,1),(rb,cr,1,1),(rb,cl,1,-1)]
        for idx,(r,c,dr,dc) in enumerate(order):
            col = colors[order[idx-1]]  # predecessor in CW order moves into this corner
            a,b=r+dr,c+dc
            while 0<=a<h and 0<=b<w:
                if grid[a][b]!=2: out[a][b]=col
                a+=dr; b+=dc
    return out
